def solve_exam_schedule(n, m, exams):
    from collections import defaultdict

    # Initialize schedule with zero (rest)
    schedule = [0] * n

    # Dictionary to track preparation days for each exam
    preparation_days = defaultdict(list)

    # Fill the schedule with preparation days
    for i, (s_i, d_i, c_i) in enumerate(exams):
        days_needed = c_i
        for day in range(s_i, d_i):
            if days_needed > 0:
                preparation_days[i + 1].append(day - 1)
                days_needed -= 1
        if days_needed > 0:
            return [-1]  # Not enough days to prepare

    # Assign preparation days to schedule
    for exam_id, days in preparation_days.items():
        for day in days:
            if schedule[day] != 0:
                return [-1]  # Conflicting preparation days
            schedule[day] = exam_id

    # Schedule the exams on their respective days
    for i, (s_i, d_i, c_i) in enumerate(exams):
        exam_id = i + 1
        if schedule[d_i - 1] == 0:
            schedule[d_i - 1] = exam_id
        else:
            return [-1]  # Conflict with scheduled exam or preparation

    # Assign rest days (0) where no preparation or exam is scheduled
    for day in range(n):
        if schedule[day] == 0:
            schedule[day] = 0

    return schedule

