    schedule = [0] * n
    exam_prep = [0] * (m + 1)

    exams.sort(key=lambda x: x[1])  # Sort exams by deadline

    for i, (start, deadline, prep_days) in enumerate(exams, 1):
        days_left = deadline - start
        can_prepare = False

        for day in range(start, deadline):
            if exam_prep[i] == 0 and days_left >= 0:
