                exam_prep[i] += 1
                days_left -= 1
            elif exam_prep[i] > 0 and days_left >= 0:
                exam_prep[i] += 1
                days_left -= 1

            if exam_prep[i] == prep_days:
                can_prepare = True
                break

        if not can_prepare:
            return [-1]

    for i in range(n):
        if schedule[i] == 0:
            schedule[i] = m + 1

    return schedule

