def solve():
    n, m = map(int, input().split())
    exams = [list(map(int, input().split())) for _ in range(m)]

    # Sort exams by their end day
    exams.sort(key=lambda x: x[1])

    schedule = [0] * n
    exam_days = set()

    for i, (s, d, c) in enumerate(exams, 1):
        prepare_days = 0
        for day in range(s - 1, d - 1):
            if prepare_days == c:
                break
            if schedule[day] == 0:
                schedule[day] = i
                prepare_days += 1

        if prepare_days < c:
            return [-1]

    for i, (s, d, _) in enumerate(exams, 1):
        for day in range(s, d):
            if schedule[day] == 0:
                schedule[day] = m + 1
                exam_days.add(day)

    if len(exam_days) != m:
        return [-1]

    return schedule

