def solve_petya_schedule(n, m, exams):
    schedule = [0] * n
    exam_days = [0] * (n + 1)
    prepare_days = [0] * (n + 1)

    # Mark exam days
    for i, (s, d, c) in enumerate(exams, 1):
        for day in range(s, d):
            exam_days[day] = i
        prepare_days[i] = c

    for day in range(1, n + 1):
        if exam_days[day] == 0:
            # If it's not an exam day, try to prepare for an exam
            for i in range(1, m + 1):
                if prepare_days[i] > 0 and exam_days[day] == 0:
                    schedule[day - 1] = i
                    prepare_days[i] -= 1
                    break
        else:
            # If it's an exam day, pass the exam
            schedule[day - 1] = exam_days[day]

    # Check if all exams were prepared
    if any(prepare > 0 for prepare in prepare_days[1:]):
        return [-1]

    return schedule

